/// <summary>
/// Extension of table TMSCarrier
/// </summary>
[ExtensionOf(tableStr(TMSCarrier))]
final class AVATMSCarrierDbt_Extension
{
}

Method.Source:
/// <summary>
/// finds primary postal address for provided TMSCarrier recId
/// </summary>
/// <param name = "_recId">TMSCarrierRecId</param>
/// <returns>LogisticsPostalAddress</returns>
public static LogisticsPostalAddress avaPrimaryPostalAddress(TMSCarrierRecId _recId)
{
    TMSCarrierLogisticsLocation avaCarrierLocation;

    select firstonly avaCarrierLocation
    where avaCarrierLocation.Carrier == _recId
        &&  avaCarrierLocation.IsPostalAddress == NoYes::Yes
        &&  avaCarrierLocation.IsPrimary == NoYes::Yes;

    return LogisticsPostalAddress::findByLocation(avaCarrierLocation.Location);
}
